import * as THREE from 'three';
// Opaque terrain with mild noise displacement; a marsh/water plane is a separate object and never the floor.
export function makeTerrain(size = 240, seg = 96) {
  const geo = new THREE.PlaneGeometry(size, size, seg, seg); geo.rotateX(-Math.PI / 2);
  const p = geo.attributes.position;
  for (let i = 0; i < p.count; i++) {
    const u = Math.min(1, Math.max(0, p.getX(i) / size + 0.5)), v = Math.min(1, Math.max(0, p.getZ(i) / size + 0.5)); // clamp: NaN crashes the turn
    const y = 0.35 * Math.sin(u * 19.3) * Math.cos(v * 23.1) + 0.12 * Math.sin(u * 71.0 + v * 53.0);
    p.setY(i, Number.isFinite(y) ? y : 0);
  }
  geo.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({ color: 0x5a5347, roughness: 0.95, metalness: 0, flatShading: true,
    transparent: false, opacity: 1, depthWrite: true });               // the floor is never see-through
  const ground = new THREE.Mesh(geo, mat); ground.receiveShadow = true; ground.userData.tag = 'terrain';
  return ground;
}
export function groundHeight(terrain, x, z) {                          // sample so the player and props sit on the surface
  const hit = new THREE.Raycaster(new THREE.Vector3(x, 50, z), new THREE.Vector3(0, -1, 0)).intersectObject(terrain)[0];
  return hit ? hit.point.y : 0;
}
export function bury(obj, terrain, fraction = 0.35) {                  // >= 30% of the object's height below the surface
  const box = new THREE.Box3().setFromObject(obj), h = box.max.y - box.min.y, gy = groundHeight(terrain, obj.position.x, obj.position.z);
  obj.position.y += gy - box.min.y - h * fraction;
  const ring = new THREE.Mesh(new THREE.TorusGeometry(Math.max(box.max.x - box.min.x, box.max.z - box.min.z) * 0.55, 0.18, 6, 24), terrain.material);
  ring.rotation.x = Math.PI / 2; ring.position.set(obj.position.x, gy + 0.05, obj.position.z);   // displaced rim: reads "buried", not "sitting on"
  ring.userData.tag = 'terrain'; terrain.parent.add(ring);
}
